return [
  {
    json: {
      type: 'telegram',
      chat_id: '-100XXXXXXXXXX',   // ID Telegram-группы (узнать: @userinfobot)
      chat_name: 'IT Kazakhstan',
      bot_token: '{{ $vars.TELEGRAM_BOT_TOKEN }}',
    }
  },
  {
    json: {
      type: 'telegram',
      chat_id: '-100YYYYYYYYYY',
      chat_name: 'Маркетинг Алматы',
      bot_token: '{{ $vars.TELEGRAM_BOT_TOKEN }}',
    }
  },
  {
    json: {
      type: 'whatsapp',
      chat_id: 'GROUP_PHONE_OR_ID@g.us',
      chat_name: 'B2B Казахстан',
      wa_token: '{{ $vars.WHATSAPP_API_TOKEN }}',
      wa_phone_id: '{{ $vars.WHATSAPP_PHONE_ID }}',
    }
  }
];

const updates = $input.first().json.result || [];
const chatId = $('Разделить: TG / WA').first().json.chat_id;
const chatName = $('Разделить: TG / WA').first().json.chat_name;

const messages = [];
let maxUpdateId = 0;

for (const update of updates) {
  const updateId = update.update_id;
  if (updateId > maxUpdateId) maxUpdateId = updateId;

  const msg = update.message || update.channel_post;
  if (!msg) continue;
  if (String(msg.chat?.id) !== String(chatId)) continue;

  const from = msg.from || {};
  messages.push({
    source: 'telegram',
    chat_id: String(chatId),
    chat_name: chatName,
    message_id: String(msg.message_id),
    user_id: String(from.id || 'channel'),
    user_name: from.first_name || '',
    username: from.username || '',
    text: msg.text || msg.caption || '',
    datetime: new Date(msg.date * 1000).toISOString(),
    next_offset: maxUpdateId + 1,
  });
}

return messages.map(m => ({ json: m }));

// WhatsApp Cloud API — парсинг сообщений
const data = $input.first().json;
const chatId = $('Разделить: TG / WA').last().json.chat_id;
const chatName = $('Разделить: TG / WA').last().json.chat_name;

const messages = [];
const entries = data.data || data.messages || [];

for (const msg of entries) {
  if (msg.type !== 'text') continue;
  messages.push({
    source: 'whatsapp',
    chat_id: chatId,
    chat_name: chatName,
    message_id: String(msg.id || ''),
    user_id: String(msg.from || ''),
    user_name: '',
    username: String(msg.from || ''),
    text: msg.text?.body || '',
    datetime: msg.timestamp
      ? new Date(parseInt(msg.timestamp) * 1000).toISOString()
      : new Date().toISOString(),
  });
}

return messages.map(m => ({ json: m }));

// Фильтр: пустые и очень короткие сообщения
const items = $input.all();
return items.filter(item => {
  const text = item.json.text || '';
  return text.trim().length >= 15;
});

