const input = $input.first().json;
const prevJson = $('Фильтр коротких').first().json;

let analysis = {};
try {
  const raw = input.message?.content || input.choices?.[0]?.message?.content || '{}';
  analysis = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  analysis = {
    keywords: [],
    topics: [],
    intent: 'нерелевантно',
    relevance_score: 0,
    is_target: false,
    reason: 'Ошибка разбора AI ответа',
    summary: '',
  };
}

return [{
  json: {
    ...prevJson,
    ...analysis,
    keywords: analysis.keywords || [],
    topics: analysis.topics || [],
    intent: analysis.intent || 'нерелевантно',
    relevance_score: parseFloat(analysis.relevance_score || 0),
    is_target: analysis.is_target || false,
    ai_summary: analysis.summary || '',
    ai_reason: analysis.reason || '',
  }
}];

