const aiProfileRaw = $input.first().json;
const prevData = $('Парсинг AI ответа').first().json;

let profile = {};
try {
  const raw = aiProfileRaw.message?.content || aiProfileRaw.choices?.[0]?.message?.content || '{}';
  profile = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  profile = { is_decision_maker: false, profile_score: 0, tags: [], profile_summary: '' };
}

// Итоговый скор: взвешенная сумма
const msgScore = parseFloat(prevData.relevance_score || 0);
const profScore = parseFloat(profile.profile_score || 0);
const finalScore = msgScore * 0.7 + profScore * 0.3;

const THRESHOLD = 0.65; // порог для алерта (меняй под себя)

return [{
  json: {
    ...prevData,
    profile_score: profScore,
    profile_tags: profile.tags || [],
    profile_summary: profile.profile_summary || '',
    is_decision_maker: profile.is_decision_maker || false,
    final_score: Math.round(finalScore * 100) / 100,
    should_alert: finalScore >= THRESHOLD,
    threshold: THRESHOLD,
  }
}];

const d = $json;
const scorePercent = Math.round(d.final_score * 100);
const tags = (d.profile_tags || []).join(', ') || 'не определено';
const keywords = (d.keywords || []).slice(0, 5).join(', ') || '-';
const topics = (d.topics || []).join(', ') || '-';

const intentMap = {
  'ищет_подрядчика': '🔥 ИЩЕТ ПОДРЯДЧИКА',
  'нанимает': '💼 Нанимает сотрудников',
  'ищет_работу': '👤 Ищет работу',
  'продаёт': '📦 Продаёт',
  'обсуждает': '💬 Обсуждает тему',
  'спрашивает': '❓ Задаёт вопрос',
  'спам': '🚫 Спам',
};

const intentLabel = intentMap[d.intent] || d.intent;

const text = [
  `🎯 *Новый целевой контакт* — ${scorePercent}% релевантности`,
  ``,
  `📍 *Чат:* ${d.chat_name} (${d.source})`,
  `👤 *Отправитель:* ${d.user_name || 'неизвестно'} ${d.username ? '@' + d.username : ''}`,
  `🎭 *Портрет:* ${tags}`,
  `📌 *Намерение:* ${intentLabel}`,
  `🔑 *Ключевые слова:* ${keywords}`,
  `📂 *Темы:* ${topics}`,
  ``,
  `💬 *Сообщение:*`,
  `_${d.text.slice(0, 300)}${d.text.length > 300 ? '...' : ''}_`,
  ``,
  `🤖 *AI-разбор:* ${d.ai_summary || d.ai_reason || ''}`,
].join('\n');

return [{ json: { ...d, alert_text: text } }];

