const cb = $input.first().json.callback_query;
const data = cb?.data || '';
const [action, userId, source] = data.split('_');

const statusMap = {
  save: 'saved',
  done: 'done',
  blacklist: 'blacklisted',
};

return [{
  json: {
    action,
    user_id: userId,
    source,
    new_status: statusMap[action] || 'new',
    callback_id: cb?.id,
    message_id: cb?.message?.message_id,
    chat_id: cb?.message?.chat?.id,
    in_blacklist: action === 'blacklist',
  }
}];
